# Let's inspect which equations in A*vec are nonzero for n=2, z_idx=11
import solve_triviality
import sympy as sp
basis, bracket, parity_fn, gb_vars = solve_triviality.build_algebra(2)
def element_parity(b):
    return (parity_fn(b[0]) + parity_fn(b[1])) % 2
dim = len(basis)
f_vars = []
f_matrix = {}
for j, bj in enumerate(basis):
    for i, bi in enumerate(basis):
        if element_parity(bi) != element_parity(bj):
            var = sp.Symbol(f'phi_{i}_{j}')
            f_vars.append(var)
            f_matrix[(i, j)] = var

eq_metadata = []
equations = []
for i, X in enumerate(basis):
    for j, Y in enumerate(basis):
        if i > j: continue
        pX = element_parity(X)
        pY = element_parity(Y)
        b_xy = bracket(X, Y)
        delta_f_xy = [0] * dim
        for k, Zk in enumerate(basis):
            if (k, j) in f_matrix:
                phi_k_j = f_matrix[(k, j)]
                b_xz = bracket(X, Zk)
                for m, W in enumerate(basis):
                    if W in b_xz:
                        delta_f_xy[m] += (-1)**pX * phi_k_j * b_xz[W]
        for k, Zk in enumerate(basis):
            if (k, i) in f_matrix:
                phi_k_i = f_matrix[(k, i)]
                b_yz = bracket(Y, Zk)
                for m, W in enumerate(basis):
                    if W in b_yz:
                        delta_f_xy[m] -= (-1)**((pX+1)*pY) * phi_k_i * b_yz[W]
        for k, Zk in enumerate(basis):
            if Zk in b_xy:
                coeff = b_xy[Zk]
                for m, W in enumerate(basis):
                    if (m, k) in f_matrix:
                        delta_f_xy[m] -= coeff * f_matrix[(m, k)]
        for k in range(dim):
            if delta_f_xy[k] != 0:
                equations.append(delta_f_xy[k])
                eq_metadata.append((i, j, k))

Z = basis[11] # (a_p, b_p1)
vec = sp.zeros(len(f_vars), 1)
for j, Y in enumerate(basis):
    b = bracket(Z, Y)
    for i, bi in enumerate(basis):
        if bi in b:
            if (i, j) in f_matrix:
                c_idx = f_vars.index(f_matrix[(i, j)])
                vec[c_idx, 0] += b[bi]

for r, eq in enumerate(equations):
    # evaluate eq with vec
    val = sum(eq.coeff(f_vars[c]) * vec[c, 0] for c in range(len(f_vars)))
    if val != 0:
        i, j, k = eq_metadata[r]
        print(f'Eq {r}: X={basis[i]}, Y={basis[j]}, proj on {basis[k]}: val={val}')
