# What if basis is constructed strictly using all pairs with order(u) <= order(v)?
import solve_triviality
osc = []
osc.append(('a', 'p', 0))
osc.append(('a', 'm', 0))
for n in [1, 2, 3]:
    osc_n = osc[:2]
