        osc_n.append(('b', 'p', k))
        osc_n.append(('b', 'm', k))
    def order(u):
        if u[0] == 'a':
            return 1 if u[1] == 'p' else 2
        else:
            base = 2 + 2 * (u[2] - 1)
            return base + 1 if u[1] == 'p' else base + 2
    pairs = []
    for i, u in enumerate(osc_n):
        for j, v in enumerate(osc_n):
            if order(u) <= order(v):
                # exclude (a_p, a_p) and (a_m, a_m) if fermions?
                pairs.append((u, v))
